import { MarketTimeline as marketTimelineSchema, type MarketEvent, type MarketTimeline, type MarketTimelinePoint } from "@harvest/contracts";

/**
 * SYNTHETIC Market timeline fixtures for unit tests and UI route mocks. Every price, rain total, alert and analogue
 * year here is generated by the formulas below; none is a market or weather observation. Shape: Hassan maize, today
 * Sunday 1 Nov 2026, 156 weeks back and 53 weeks ahead (210 weekly points), forecast to 6 Nov 2026.
 */
export const FIXTURE_FARM_ID = "11111111-1111-4111-8111-111111111111";
export const FIXTURE_TODAY = "2026-11-01";
export const FIXTURE_FROM = "2023-10-30";
export const FIXTURE_TODAY_INDEX = 156;
export const FIXTURE_POINTS = 210;
export const FIXTURE_ALERT_ID = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1";
export const FIXTURE_DISMISSED_ALERT_ID = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2";

const DAY_MS = 86_400_000;
const addDays = (date: string, n: number) => new Date(Date.parse(`${date}T00:00:00Z`) + n * DAY_MS).toISOString().slice(0, 10);
const r2 = (x: number) => Math.round(x * 100) / 100;
function isoWeek(date: string): { year: number; week: number } {
  const t = new Date(`${date}T00:00:00Z`);
  t.setUTCDate(t.getUTCDate() + 4 - (t.getUTCDay() || 7));
  const year = t.getUTCFullYear();
  return { year, week: Math.ceil(((t.getTime() - Date.UTC(year, 0, 1)) / DAY_MS + 1) / 7) };
}
const label = (monday: string) => {
  const w = isoWeek(monday);
  return `${w.year}-W${String(w.week).padStart(2, "0")}`;
};

const alertEvent = (id: string, title: string, date: string, dismissed: boolean, type: "crop_threat" | "weather", severity: MarketEvent["severity"]): MarketEvent => ({
  id,
  kind: "alert",
  type,
  severity,
  title,
  detail: "Synthetic fixture alert for interface tests, not a real event.",
  date,
  source: { name: "Fixture crop guide", url: "https://example.org/fixture-guide", date },
  alertId: id,
  dismissed,
});

function point(i: number): MarketTimelinePoint {
  const weekStart = addDays(FIXTURE_FROM, 7 * i);
  const t = (2 * Math.PI * i) / 52;
  let price: MarketTimelinePoint["price"];
  if (i <= FIXTURE_TODAY_INDEX) {
    const p50 = r2(20 + 2 * Math.sin(t));
    price = i % 11 === 5 ? { kind: "none", reason: "no_quotes_this_week" } : { kind: "observed", p50, min: r2(p50 - 1.5), max: r2(p50 + 2), n: 6, markets: 3 };
  } else {
    const p50 = r2(21 + 1.5 * Math.sin(t));
    price = { kind: "reference", p50, likely: { low: r2(p50 - 0.6), high: r2(p50 + 0.7) }, possible: { low: r2(p50 - 1.4), high: r2(p50 + 1.6) }, yearsUsed: [2023, 2024, 2025], observations: 40 };
  }
  let weather: MarketTimelinePoint["weather"];
  if (i < FIXTURE_TODAY_INDEX) weather = { kind: "observed", rainMm: 20 + (i % 5) * 3, tMaxC: 29, tMinC: 19, days: 7 };
  else if (i === FIXTURE_TODAY_INDEX) weather = { kind: "observed", rainMm: 6, tMaxC: 30, tMinC: 19, days: 6 };
  else if (i === FIXTURE_TODAY_INDEX + 1) weather = { kind: "forecast", rainMm: 12, tMaxC: 31, tMinC: 21, days: 5 };
  else weather = { kind: "typical", rainMm: 28, tMaxC: 29.4, tMinC: 18.2, days: 7 };
  const events: MarketEvent[] = [];
  if (i === 155 || i === 156) events.push(alertEvent(FIXTURE_ALERT_ID, "Fall armyworm scouting window", "2026-10-20", false, "crop_threat", "watch"));
  if (i === 135) events.push(alertEvent(FIXTURE_DISMISSED_ALERT_ID, "Heavy rain warning", "2026-06-01", true, "weather", "warning"));
  if (i === 148)
    events.push({
      id: "price_move:2026-08-31",
      kind: "price_move",
      type: "price",
      severity: "info",
      title: "Mandi price up 25% this week",
      detail: "Weekly median ₹25.0/kg against ₹20.0/kg, the median of the previous 4 weekly medians (Hassan district mandis, 6 markets). Wholesale modal prices, not farm-gate prices; computed from stored quotes.",
      date: "2026-09-06",
      source: { name: "data.gov.in: Variety-wise Daily Market Prices Data of Commodity", url: "https://api.data.gov.in/resource/35985678-0d79-46b4-9ed6-6f13308a1d24", date: "2026-09-06" },
      alertId: null,
      dismissed: false,
    });
  return { weekStart, weekEnd: addDays(weekStart, 6), isoWeek: label(weekStart), price, weather, events };
}

/** 52 weekly medians of a past crop year (July to June), keyed by ISO week number. */
function path(offset: number): { isoWeek: number; p50: number }[] {
  const weeks = [...Array.from({ length: 25 }, (_, k) => 28 + k), ...Array.from({ length: 27 }, (_, k) => 1 + k)];
  return weeks.map((w, k) => ({ isoWeek: w, p50: r2(19 + offset + 2.2 * Math.sin((2 * Math.PI * (k + 3)) / 52)) }));
}

export function marketFixture(farmId = FIXTURE_FARM_ID): MarketTimeline {
  const points = Array.from({ length: FIXTURE_POINTS }, (_, i) => point(i));
  return marketTimelineSchema.parse({
    farmId,
    productId: "maize-grain",
    productName: "Maize grain",
    cropName: "Maize",
    asOf: "2026-11-01T04:30:00.000Z",
    today: FIXTURE_TODAY,
    from: FIXTURE_FROM,
    to: points.at(-1)!.weekEnd,
    todayIndex: FIXTURE_TODAY_INDEX,
    scope: { level: "district", stateName: "Karnataka", districtName: "Hassan", marketCount: 6, label: "Hassan district mandis, 6 markets" },
    unit: "INR/kg",
    forecastHorizonEnd: "2026-11-06",
    harvestWindow: { earliest: "2027-01-03", latest: "2027-01-08" },
    points,
    analogues: {
      status: "available",
      reason: null,
      thisSeason: { cropYear: "2026-27", rainMm: 1098, observedThrough: "2026-09-30", typicalRemainderMm: 0 },
      years: [
        { cropYear: "2025-26", rainMm: 1220, similarity: 0.889, pricePath: path(1), harvestChangePct: 8.4 },
        { cropYear: "2024-25", rainMm: 915, similarity: 0.833, pricePath: path(0), harvestChangePct: -3.1 },
        { cropYear: "2023-24", rainMm: 732, similarity: 0.667, pricePath: path(-1), harvestChangePct: null },
      ],
    },
    band: { likely: "p25_p75", possible: "p10_p90" },
    limitations: [
      "Years with similar rain are a selection of history, not a forecast: they show how mandi prices moved in past crop years whose 1 June to 30 September rain at this field was closest to this season's.",
      "Synthetic fixture for interface tests; not market or weather observations.",
    ],
  });
}

/** A product with no stored price series: every week has price kind none. */
export function marketNoPriceFixture(farmId = FIXTURE_FARM_ID): MarketTimeline {
  const base = marketFixture(farmId);
  return marketTimelineSchema.parse({
    ...base,
    productId: "sugarcane-cane",
    productName: "Sugarcane",
    cropName: "Sugarcane",
    harvestWindow: null,
    scope: { level: "state", stateName: "Karnataka", districtName: null, marketCount: 0, label: "Sugarcane in Karnataka: no verified mandi price series is stored" },
    points: base.points.map((p) => ({ ...p, price: { kind: "none", reason: "price_history_not_ingested" }, events: p.events.filter((e) => e.kind === "alert") })),
    analogues: { status: "insufficient", reason: "Fewer than two past crop years have both complete June to September rain at the field and mandi prices (found 0).", thisSeason: base.analogues.thisSeason, years: [] },
  });
}

/** Prices but fewer than two analogue years. */
export function marketInsufficientFixture(farmId = FIXTURE_FARM_ID): MarketTimeline {
  const base = marketFixture(farmId);
  return marketTimelineSchema.parse({
    ...base,
    analogues: { status: "insufficient", reason: "Fewer than two past crop years have both complete June to September rain at the field and mandi prices (found 1).", thisSeason: base.analogues.thisSeason, years: [] },
  });
}
